import type { HTMLAttributes } from 'react'

import { cx } from '~/lib/cx'
import styles from './badge.module.scss'

export type BadgeVariant =
  | 'primary'
  | 'secondary'
  | 'outline'
  | 'destructive'
  | 'success'
  | 'soft'

export type BadgeSize = 'sm' | 'md' | 'lg'

const VARIANT: Record<BadgeVariant, string> = {
  primary: styles.primary,
  secondary: styles.secondary,
  outline: styles.outline,
  destructive: styles.destructive,
  success: styles.success,
  soft: styles.soft,
}

const SIZE: Record<BadgeSize, string> = {
  sm: styles.sm,
  md: '',
  lg: styles.lg,
}

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: BadgeVariant
  size?: BadgeSize
}

export function Badge({
  className,
  variant = 'primary',
  size = 'md',
  ...props
}: BadgeProps) {
  return (
    <span
      className={cx(styles.root, VARIANT[variant], SIZE[size], className)}
      {...props}
    />
  )
}

@use 'styles' as vz;

.root {
  --badge-bg: transparent;
  --badge-fg: currentcolor;
  --badge-border: transparent;
  --badge-font-size: #{vz.font-size('xs')};
  --badge-line-height: 1rem;

  display: inline-flex;
  align-items: center;
  gap: vz.space(1);
  padding: 0.125rem 0.625rem;
  border: 1px solid var(--badge-border);
  border-radius: vz.radius('full');
  background: var(--badge-bg);
  color: var(--badge-fg);
  font-size: var(--badge-font-size);
  font-weight: 500;
  line-height: var(--badge-line-height);
  white-space: nowrap;
}

.primary {
  --badge-bg: #{vz.color('primary')};
  --badge-fg: #{vz.color('primary-foreground')};
}

.secondary {
  --badge-bg: #{vz.color('secondary')};
  --badge-fg: #{vz.color('secondary-foreground')};
}

.outline {
  --badge-bg: #{vz.color('background')};
  --badge-fg: #{vz.color('foreground')};
  --badge-border: #{vz.color('border')};
}

.destructive {
  --badge-bg: #{vz.color('destructive')};
  --badge-fg: #{vz.color('destructive-foreground')};
}

.success {
  --badge-bg: #{vz.color('success')};
  --badge-fg: #{vz.color('success-foreground')};
}

.soft {
  --badge-bg: #{vz.color('accent')};
  --badge-fg: #{vz.color('accent-foreground')};
  --badge-border: #{vz.color('border', 0.6)};
}

.sm {
  --badge-font-size: 10px;
  --badge-line-height: 0.875rem;

  padding-block: 0;
  padding-inline: vz.space(2);
}

.lg {
  --badge-font-size: #{vz.font-size('sm')};
  --badge-line-height: 1.25rem;

  padding: 0.25rem vz.space(3);
}
